// Native document-command view positioning and full regeneration.
using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Web.Script.Serialization;
using Autodesk.AutoCAD.Runtime;using Autodesk.AutoCAD.ApplicationServices;using Autodesk.AutoCAD.DatabaseServices;using Autodesk.AutoCAD.Geometry;using Autodesk.AutoCAD.EditorInput;
using App=Autodesk.AutoCAD.ApplicationServices.Core.Application;
public class NativeViewV1 {
 public class Host{public int pid;public long created;public string image;}
 public class Manifest{public Host host;public string request,request_sha256,loaded_dll,loaded_dll_sha256,session_dir;}
 public class Request{public string kind,job_path,job_sha256;}
 public class ViewJob{public string input,input_sha256,layout,receipt,image;public double x,y,width,height;public string[] handles;public double[] bounds;}
 static readonly JavaScriptSerializer J=new JavaScriptSerializer{MaxJsonLength=50000000};static readonly BindingFlags F=BindingFlags.NonPublic|BindingFlags.Static;
 static void Need(bool b,string m){if(!b)throw new InvalidOperationException(m);}
 static object Get(Type t,string n){return t.GetField(n,F).GetValue(null);}static object Call(Type t,string n,params object[] a){return t.GetMethod(n,F).Invoke(null,a);}
 static bool Eq(string a,string b){return String.Equals(Path.GetFullPath(a),Path.GetFullPath(b),StringComparison.OrdinalIgnoreCase);}
 static void Stage(ViewJob j,string s){File.WriteAllText(j.receipt+".progress.json",J.Serialize(new{stage=s,pid=System.Diagnostics.Process.GetCurrentProcess().Id,input=j.input,source_sha256=j.input_sha256}),new System.Text.UTF8Encoding(false));}
 static void Write(string p,object o){using(var f=new FileStream(p,FileMode.CreateNew))using(var w=new StreamWriter(f,new System.Text.UTF8Encoding(false)))w.Write(J.Serialize(o));}
 static void Position(Document doc,ViewJob j){
  Need(j.width>0&&j.height>0,"VIEW_SIZE");Stage(j,"NATIVE_LAYOUT");bool paper=j.layout!="Model";
  if(doc.Database.TileMode==paper)doc.Database.TileMode=!paper;if(LayoutManager.Current.CurrentLayout!=j.layout)LayoutManager.Current.CurrentLayout=j.layout;
  if(paper&&Convert.ToInt32(App.GetSystemVariable("CVPORT"))!=1)doc.Editor.Command("_.PSPACE");
  Stage(j,"NATIVE_ZOOM");using(var view=doc.Editor.GetCurrentView()){if(!paper&&(Math.Abs(view.ViewTwist)>1e-10||(view.ViewDirection.GetNormal()-Vector3d.ZAxis).Length>1e-10))doc.Editor.Command("_.PLAN","_W");doc.Editor.Command("_.ZOOM","_C",new Point3d(j.x,j.y,0),Math.Max(j.height,j.width*view.Height/view.Width));}
  Stage(j,"NATIVE_REGENALL");doc.Editor.Command("_.REGENALL");Stage(j,"NATIVE_REFRESH_COMPLETE");
 }
 [CommandMethod("HLCADNATIVEVIEWV2",CommandFlags.Modal)]public void Run(){
  var a=App.DocumentManager.MdiActiveDocument.Editor.GetString(new PromptStringOptions("\nNative view manifest: "){AllowSpaces=true});if(a.Status!=PromptStatus.OK)return;Type adapter=null;ViewJob j=null;bool busy=false;
  try{var m=J.Deserialize<Manifest>(File.ReadAllText(a.StringResult.Trim('"')));var p=System.Diagnostics.Process.GetCurrentProcess();Need(p.Id==m.host.pid&&p.StartTime.ToUniversalTime().ToFileTimeUtc()==m.host.created&&Eq(p.MainModule.FileName,m.host.image),"HOST_IDENTITY");adapter=AppDomain.CurrentDomain.GetAssemblies().Select(x=>x.GetType("V736BaseSession",false)).Single(x=>x!=null);CadAdapterContractV1.Check(adapter);Need(Eq(adapter.Assembly.Location,m.loaded_dll)&&NativeGeometryReadV1.Hash(m.loaded_dll)==m.loaded_dll_sha256&&Eq((string)Get(adapter,"dir"),m.session_dir),"ADAPTER_IDENTITY");Need(!(bool)Get(adapter,"busy")&&!(bool)Get(adapter,"blocked")&&!File.Exists(Path.Combine(m.session_dir,"request.json")),"SESSION_BUSY");Need(Eq(Path.GetDirectoryName(m.request),m.session_dir)&&NativeGeometryReadV1.Hash(m.request)==m.request_sha256,"REQUEST_IDENTITY");var q=J.Deserialize<Request>(File.ReadAllText(m.request));Need(q.kind=="inspect"&&NativeGeometryReadV1.Hash(q.job_path)==q.job_sha256,"VIEW_JOB_REQUIRED");j=J.Deserialize<ViewJob>(File.ReadAllText(q.job_path));Call(adapter,"CheckLive",j.input,j.input_sha256);Call(adapter,"CheckPath",j.receipt);Need(!File.Exists(j.receipt),"VIEW_RECEIPT_EXISTS");var doc=(Document)Get(adapter,"doc");Need(doc==App.DocumentManager.MdiActiveDocument,"LIVE_DOCUMENT_CHANGED");adapter.GetField("busy",F).SetValue(null,true);busy=true;
   if(j.handles!=null)foreach(string handle in j.handles){ObjectId id;try{id=doc.Database.GetObjectId(false,new Handle(Convert.ToInt64(handle,16)),0);}catch(Autodesk.AutoCAD.Runtime.Exception ex){if(ex.ErrorStatus==ErrorStatus.UnknownHandle)throw new InvalidOperationException("READ_HANDLE_NOT_FOUND:"+handle);throw;}Need(!id.IsNull&&!id.IsErased,"READ_HANDLE_ERASED:"+handle);}
   var dict=J.Deserialize<Dictionary<string,object>>(File.ReadAllText(q.job_path));dict["image"]=null;dict["receipt"]=j.receipt+".read.json";var read=J.Deserialize(J.Serialize(dict),adapter.GetNestedType("Inspect"));Call(adapter,"InspectRegion",read);
   if(!String.IsNullOrEmpty(j.image))Position(doc,j);Call(adapter,"CheckLive",j.input,j.input_sha256);var row=J.Deserialize<Dictionary<string,object>>(File.ReadAllText((string)dict["receipt"]));row["image"]=j.image;row["layout"]=j.layout;row["actual_layout"]=App.GetSystemVariable("CTAB");row["cvport"]=App.GetSystemVariable("CVPORT");row["view_method"]=String.IsNullOrEmpty(j.image)?"READ_ONLY_NO_VIEW_CHANGE":"NATIVE_DOCUMENT_ZOOM_REGENALL";Write(j.receipt,row);
  }catch(System.Exception e){if(e is TargetInvocationException&&e.InnerException!=null)e=e.InnerException;if(j!=null&&!File.Exists(j.receipt))Write(j.receipt,new{status="REJECTED_BEFORE_WRITE",source_sha256=j.input_sha256,write_started=false,committed=false,replayed=false,emergency=(string)null,error=e.ToString()});}
  finally{if(busy)adapter.GetField("busy",F).SetValue(null,false);}
 }
 public class Recovery:Manifest{public string failure,failure_sha256,resolution;}
 [CommandMethod("HLCADREADHOLDRECOVERV2",CommandFlags.Session)]public void RecoverReadHold(){
  var answer=App.DocumentManager.MdiActiveDocument.Editor.GetString(new PromptStringOptions("\nRead-only hold recovery: "){AllowSpaces=true});if(answer.Status!=PromptStatus.OK)return;Recovery m=null;
  try{m=J.Deserialize<Recovery>(File.ReadAllText(answer.StringResult.Trim('"')));var p=System.Diagnostics.Process.GetCurrentProcess();Need(p.Id==m.host.pid&&p.StartTime.ToUniversalTime().ToFileTimeUtc()==m.host.created&&Eq(p.MainModule.FileName,m.host.image),"HOST_IDENTITY");
   var adapter=AppDomain.CurrentDomain.GetAssemblies().Select(x=>x.GetType("V736BaseSession",false)).Single(x=>x!=null);CadAdapterContractV1.Check(adapter);Need(Eq(adapter.Assembly.Location,m.loaded_dll)&&NativeGeometryReadV1.Hash(m.loaded_dll)==m.loaded_dll_sha256&&Eq((string)Get(adapter,"dir"),m.session_dir),"ADAPTER_IDENTITY");Need((bool)Get(adapter,"blocked")&&!(bool)Get(adapter,"busy")&&!File.Exists(Path.Combine(m.session_dir,"request.json")),"IDLE_HOLD_REQUIRED");
   Need(Eq(Path.GetDirectoryName(m.request),m.session_dir)&&NativeGeometryReadV1.Hash(m.request)==m.request_sha256,"REQUEST_IDENTITY");var q=J.Deserialize<Request>(File.ReadAllText(m.request));Need((q.kind=="inspect"||q.kind=="page_map")&&NativeGeometryReadV1.Hash(q.job_path)==q.job_sha256,"READ_ONLY_REQUEST_REQUIRED");var j=J.Deserialize<ViewJob>(File.ReadAllText(q.job_path));Need(String.IsNullOrEmpty(j.image)&&j.bounds==null&&!File.Exists(j.receipt)&&(q.kind=="inspect"?j.handles!=null&&j.handles.Length>0:!String.IsNullOrEmpty(j.layout)),"EXACT_READ_REQUIRED");Call(adapter,"CheckLive",j.input,j.input_sha256);Call(adapter,"CheckPath",j.receipt);
   Need(Eq(m.failure,Path.Combine(m.session_dir,"session_failure.json"))&&NativeGeometryReadV1.Hash(m.failure)==m.failure_sha256&&Eq(m.resolution,m.failure+"."+Path.GetFileNameWithoutExtension(m.request)+".read-recovery.json")&&!File.Exists(m.resolution),"FAILURE_IDENTITY");var f=J.Deserialize<Dictionary<string,object>>(File.ReadAllText(m.failure));string err=(string)f["error"];Need((string)f["status"]=="HOLD"&&Convert.ToInt32(f["pid"])==p.Id&&err.Contains("V736BaseSession.Pump")&&(q.kind=="inspect"?err.StartsWith("Autodesk.AutoCAD.Runtime.Exception: eUnknownHandle")&&err.Contains("Database.GetObjectId")&&err.Contains("V736BaseSession.InspectRegion"):err.StartsWith("System.InvalidOperationException: LAYOUT_NOT_FOUND:"+j.layout+"\r\n")&&err.Contains("V736BaseSession.PageMap")),"UNPROVEN_READ_FAILURE");var doc=(Document)Get(adapter,"doc");Need(doc==App.DocumentManager.MdiActiveDocument&&Eq(doc.Name,(string)f["live"])&&doc.Database.TransactionManager.NumberOfActiveTransactions==0,"DOCUMENT_NOT_IDLE");
   var missing=new List<string>();foreach(string h in q.kind=="inspect"?j.handles:new string[0]){try{var id=doc.Database.GetObjectId(false,new Handle(Convert.ToInt64(h,16)),0);if(id.IsNull||id.IsErased)missing.Add(h);}catch(Autodesk.AutoCAD.Runtime.Exception ex){if(ex.ErrorStatus!=ErrorStatus.UnknownHandle)throw;missing.Add(h);}}if(q.kind=="inspect")Need(missing.Count>0,"MISSING_HANDLE_NOT_REPRODUCED");else using(var tr=doc.Database.TransactionManager.StartTransaction()){var layouts=(DBDictionary)tr.GetObject(doc.Database.LayoutDictionaryId,OpenMode.ForRead);Need(!layouts.Contains(j.layout),"MISSING_LAYOUT_NOT_REPRODUCED");}string emergency=(string)f["emergency"];Call(adapter,"CheckPath",emergency);Call(adapter,"VerifyDwg",emergency);string emergencyHash=NativeGeometryReadV1.Hash(emergency);string archived=m.failure+"."+m.failure_sha256+".preserved";Need(!File.Exists(archived),"FAILURE_ALREADY_ARCHIVED");
   Write(j.receipt,new{status="REJECTED_BEFORE_WRITE",source_sha256=j.input_sha256,write_started=false,committed=false,replayed=false,emergency=(string)null,error=q.kind=="inspect"?"READ_HANDLE_NOT_FOUND:"+String.Join(",",missing):"LAYOUT_NOT_FOUND:"+j.layout,preserved_failure=archived});File.Move(m.failure,archived);adapter.GetField("blocked",F).SetValue(null,false);Call(adapter,"State");Write(m.resolution,new{status="READ_ONLY_HOLD_RECOVERED",request=m.request,source_sha256=j.input_sha256,pid=p.Id,created=m.host.created,missing_handles=missing,missing_layout=q.kind=="page_map"?j.layout:null,preserved_failure=archived,emergency=emergency,emergency_sha256=emergencyHash,production_entities_modified=false,replayed=false});
  }catch(System.Exception ex){if(m!=null&&!File.Exists(m.resolution))Write(m.resolution,new{status="RECOVERY_FAILED",error=ex.ToString()});}
 }
 public class TestConfig:ViewJob{public string copy;}
 [CommandMethod("HLCADQUEUEDVIEWRECOVERV1",CommandFlags.Session)]public void RecoverQueuedView(){
  var a=App.DocumentManager.MdiActiveDocument.Editor.GetString(new PromptStringOptions("\nExact queued view manifest: "){AllowSpaces=true});if(a.Status!=PromptStatus.OK)return;
  var m=J.Deserialize<Manifest>(File.ReadAllText(a.StringResult.Trim('"')));var p=System.Diagnostics.Process.GetCurrentProcess();Need(p.Id==m.host.pid&&p.StartTime.ToUniversalTime().ToFileTimeUtc()==m.host.created&&Eq(p.MainModule.FileName,m.host.image),"HOST_IDENTITY");
  var adapter=AppDomain.CurrentDomain.GetAssemblies().Select(x=>x.GetType("V736BaseSession",false)).Single(x=>x!=null);CadAdapterContractV1.Check(adapter);Need(Eq(adapter.Assembly.Location,m.loaded_dll)&&NativeGeometryReadV1.Hash(m.loaded_dll)==m.loaded_dll_sha256&&!((bool)Get(adapter,"busy"))&&!((bool)Get(adapter,"blocked")),"ADAPTER_OR_BUSY");
  Need(NativeGeometryReadV1.Hash(m.request)==m.request_sha256,"REQUEST_HASH");var q=J.Deserialize<Request>(File.ReadAllText(m.request));Need(q.kind=="inspect"&&NativeGeometryReadV1.Hash(q.job_path)==q.job_sha256,"VIEW_REQUEST_HASH");var job=J.Deserialize<ViewJob>(File.ReadAllText(q.job_path));Call(adapter,"CheckLive",job.input,job.input_sha256);Call(adapter,"CheckPath",job.receipt);
  var pending=Get(adapter,"pendingView");Need(pending!=null&&!File.Exists(job.receipt)&&Eq((string)pending.GetType().GetField("receipt").GetValue(pending),job.receipt),"EXACT_UNSTARTED_VIEW_REQUIRED");
  var stage=J.Deserialize<Dictionary<string,object>>(File.ReadAllText(job.receipt+".progress.json"));Need((string)stage["stage"]=="QUEUED_DOCUMENT_COMMAND","VIEW_ALREADY_STARTED");
  adapter.GetField("pendingView",F).SetValue(null,null);Write(job.receipt,new{status="REJECTED_BEFORE_WRITE",source_sha256=job.input_sha256,write_started=false,committed=false,replayed=false,emergency=(string)null,error="QUEUED_VIEW_COMMAND_DID_NOT_START",recovery="CLEARED_EXACT_UNSTARTED_VIEW_ONLY",dwg_unchanged=true});
 }
 static TestConfig test;static Document original,staging;static Database previous;
 [CommandMethod("HLCADNATIVEVIEWTESTV1",CommandFlags.Session)]public void Test(){
  original=App.DocumentManager.MdiActiveDocument;previous=HostApplicationServices.WorkingDatabase;var a=original.Editor.GetString(new PromptStringOptions("\nNative view test: "){AllowSpaces=true});if(a.Status!=PromptStatus.OK)return;test=J.Deserialize<TestConfig>(File.ReadAllText(a.StringResult.Trim('"')));Need(NativeGeometryReadV1.Hash(test.input)==test.input_sha256&&!File.Exists(test.copy)&&!File.Exists(test.receipt),"ISOLATED_VIEW_INPUT");File.Copy(test.input,test.copy,false);staging=App.DocumentManager.Open(test.copy,false);App.DocumentManager.MdiActiveDocument=staging;HostApplicationServices.WorkingDatabase=staging.Database;staging.SendStringToExecute("HLCADNATIVEVIEWTESTDOV1\n",true,false,false);
 }
 [CommandMethod("HLCADNATIVEVIEWTESTDOV1",CommandFlags.Modal)]public void TestView(){try{Position(staging,test);Write(test.receipt,new{status="ISOLATED_NATIVE_VIEW_POSITIONED",document=staging.Name,input=test.input,source_sha256=test.input_sha256,pid=System.Diagnostics.Process.GetCurrentProcess().Id,layout=App.GetSystemVariable("CTAB"),cvport=App.GetSystemVariable("CVPORT")});}catch(System.Exception e){Write(test.receipt,new{status="VIEW_TEST_FAILED",error=e.ToString()});}}
 [CommandMethod("HLCADNATIVEVIEWTESTCLOSEV1",CommandFlags.Session)]public void CloseTest(){if(staging==null)return;App.DocumentManager.MdiActiveDocument=original;HostApplicationServices.WorkingDatabase=previous;staging.CloseAndDiscard();staging=null;}
}
